import {readFileSync} from 'node:fs';
import spec0 from '../../productions/tiki_tiki_48s/spec.ts';
import {normalizeCompilerTimeline} from '../../scripts/v0/optimizer/compiler_input.ts';
import {applyJolt,resolveJoltMs} from '../../scripts/produce/seed.ts';
import {captureArcFork} from '../../scripts/v0/optimizer/arc_guide_study.ts';
import {compileArcMotion} from '../../scripts/v0/optimizer/arc_motion.ts';
import {connectedArcOptions} from '../../scripts/v0/optimizer/connected_arcs.ts';
import {writeGalleryJson,replayGalleryTrack} from '../../scripts/gallery/artifacts.ts';
const root='generated/connected-repertoire-20260930/review', read=(p:string)=>JSON.parse(readFileSync(root+'/'+p,'utf8'));
const source=read('tiki_tiki_48s-381-baseline.json'), rows=read('tiki_tiki_48s-381-baseline/construction.json').rows;
const styles=read('tiki_tiki_48s-381-candidate/construction.json').styles;
const spec=normalizeCompilerTimeline(applyJolt(spec0,resolveJoltMs())), c=read('manifest.json').plan.cases.find((c:any)=>c.id==='tiki_tiki_48s');
for (const samples of [80,160]){
 const captured=captureArcFork({...source,rows} as any,28);
 const options={...connectedArcOptions(spec,1000000-captured.physicsFrames),samples,policySamples:0,memorySamples:0,memoryResponseSamples:0,collectTrajectoryLoss:true,sectionStyles:styles,
 fork:{...captured.fork,continuation:rows.slice(28).map((r:any)=>({control:r.control,incoming:r.incoming,span:r.span}))}};
 const start=performance.now(),result=compileArcMotion(spec,381,options),replay=replayGalleryTrack(result.track,c,true);
 const summary={samples,initialGenericSamples:Math.min(80,Math.ceil(samples/2)),physicalFrames:captured.physicsFrames+result.stats.sim_frames,seconds:(performance.now()-start)/1000,valid:replay.grade.score.valid,rms:replay.grade.score.weightedAxisRms,failure:result.failure};
 writeGalleryJson('generated/connected-repertoire-20260930/probe-initialization',samples+'.json',{...summary,result,replay});console.log(JSON.stringify(summary));
}

import {readFileSync,mkdirSync} from 'node:fs';
import {sha} from '../../benchmark/v3/model.ts';
import {writeGalleryJson} from '../../scripts/gallery/artifacts.ts';
const root='generated/connected-repertoire-20260930',source=root+'/review',out=root+'/initialization';mkdirSync(out,{recursive:true});
const read=(p:string)=>{const bytes=readFileSync(p);if(sha(bytes)!==readFileSync(p+'.sha256','utf8').trim())throw Error('checksum '+p);return JSON.parse(bytes.toString());};
const original=read(source+'/manifest.json'),caseInfo=original.plan.cases.find((c:any)=>c.id==='tiki_tiki_48s');
const methods=['baseline','frozen','broad40','broad80'],methodDetails={baseline:{title:'Ordinary baseline'},frozen:{title:'Frozen fold: failed entry'},broad40:{title:'Fold: 40 general initial proposals'},broad80:{title:'Fold: 80 general initial proposals'}};
const inputs=[source+'/tiki_tiki_48s-381-baseline.json',source+'/tiki_tiki_48s-381-candidate.json',root+'/probe-initialization/80.json',root+'/probe-initialization/160.json'];
const plan={schema:'line.fold-initialization-diagnosis.v1',cases:[caseInfo],seeds:[381],budgets:[1000000],methods,methodDetails,
 compiler:original.plan.compiler,judge:original.plan.judge,sourceManifest:{path:source+'/manifest.json',sha256:sha(readFileSync(source+'/manifest.json'))},
 sources:inputs.map(path=>({path,sha256:sha(readFileSync(path))})),
 note:'Post-confirmation diagnosis on a known failed entry. Frozen geometry, broader generic proposal initialization, unchanged total ceiling. Not an unseen confirmation or a promoted production search policy.'};
const planSha256=writeGalleryJson(out,'plan.json',plan),cells:any[]=[];
for(const [index,path]of inputs.entries()){
 const input=read(path),method=methods[index],id=`tiki_tiki_48s-381-${method}`;
 let record:any;
 if(index<2)record={...input,id,method,planSha256,qualityRms:input.valid?input.qualityRms:null};
 else{
  const r=input.result,replay=input.replay,styles=read(inputs[1]).construction.styles;
  record={schema:'line.motion-gallery-cell.v1',planSha256,id,caseId:caseInfo.id,case:caseInfo,method,seed:381,jitter:0,budget:1000000,allowance:1000000,
   score:replay.grade.score,valid:replay.grade.score.valid,qualityRms:input.valid?input.rms:null,compileMs:input.seconds*1000,physicalFrames:input.physicalFrames,
   lines:r.track.lines.length,trackHash:sha(JSON.stringify(r.track)),track:r.track,trace:replay.trace,railLayout:'connected',
   observations:replay.grade.observations,contacts:replay.grade.contacts,offBeat:replay.grade.offBeat,terminus:replay.grade.terminus,
   failure:r.failure,construction:{styles,changedSections:Object.keys(styles).map(Number),fragmentSections:[]},
   sections:r.rows.map((row:any,i:number)=>({section:i,start:row.frame/40,end:(r.rows[i+1]?.frame??caseInfo.durationFrames)/40})),collisionSha256:sha(JSON.stringify(replay.collisionIds))};
 }
 const digest=writeGalleryJson(out,id+'.json',record),{track,trace,case:unused,...cell}=record;cells.push({...cell,path:id+'.json',sha256:digest});
}
writeGalleryJson(out,'manifest.json',{schema:'line.motion-gallery.v1',planSha256,plan,cells,summary:cells.map(c=>({method:c.method,budget:1000000,runs:1,valid:Number(c.valid),meanScore:c.score.score,totalPhysicalFrames:c.physicalFrames,totalCompileMs:c.compileMs}))});
console.log(JSON.stringify({tracks:cells.length,valid:cells.filter(c=>c.valid).length}));

import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {motionArc as current} from '../../scripts/v0/optimizer/arc_geometry.ts';
import {motionArc as frozen} from '/tmp/line-connected-repertoire-20260930/scripts/v0/optimizer/arc_geometry.ts';
import {makeRng} from '../../scripts/lib/rng.ts';
import {writeGalleryJson} from '../../scripts/gallery/artifacts.ts';
import {sha} from '../../benchmark/v3/model.ts';
const random=makeRng(207),points=[{x:0,y:0},{x:12,y:1},{x:4,y:9}],v={x:9,y:2};
let exactCases=0,zeroStrengthCases=0;
for(let i=0;i<100;i++){
 const control={entry:-30+random()*60,turn:-40+random()*80,exit:-45+random()*90,support:3+random()*40,bias:-2+4*random(),turnFraction:.1+.75*random(),offset:random()};
 for(const style of [undefined,{profile:'fold' as const,faces:3,profileStrength:1,profileStart:0,foldAngle:30}]){
  assert.deepEqual(current(points,v,control,1000,false,12,false,24,4,style),frozen(points,v,control,1000,false,12,false,24,4,style));exactCases++;
 }
 assert.deepEqual(current(points,v,control,1000,false,12,false,24,4,{profile:'fold',faces:3,profileStrength:0,profileStart:0}),current(points,v,control,1000,false,12,false,24,4,{faces:3}));zeroStrengthCases++;
}
const result={schema:'line.fold-delivery-boundary-check.v1',exactCases,zeroStrengthCases,interpretation:'Synthetic geometry checks, not musical trials. Frozen full-strength onset-zero fold and ordinary geometry match exactly. Zero fold strength now retains the ordinary radius limiter.',
 files:Object.fromEntries(['scripts/v0/optimizer/arc_geometry.ts','tests/motion_geometry_styles.test.ts',import.meta.filename].map(p=>[p,sha(readFileSync(p))]))};
writeGalleryJson('generated/connected-repertoire-20260930','delivery-geometry-check.json',result);console.log(result);

